#!/usr/bin/env node
// Renders the open-work files under audit/ from the capability ledger.
//
//   node scripts/audit-worklist.mjs          rewrite the files, delete empty ones
//   node scripts/audit-worklist.mjs --check  fail when a file is stale or orphaned
//
// Every generated file lists only unresolved work. When an item is fixed, set
// its cells to "done" (with evidence) in audit/ledger/ecosystem-capability-ledger.jsonl
// and rerun; the item leaves its file, and a file with nothing left is deleted.
import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';

const root = process.cwd();
const LEDGER = 'audit/ledger/ecosystem-capability-ledger.jsonl';
const META = 'audit/ledger/ecosystem-capability-ledger.meta.json';
const GENERATED_DIRS = ['audit/missing', 'audit/partial', 'audit/live-check'];
const GENERATED_FILE = /^\d{3}-[a-z0-9-]+\.md$/;
const WAVES = 'audit/plan/waves.md';
const SURFACES = ['web', 'desktop', 'mobile', 'cli', 'vscode', 'chrome', 'api', 'platform'];
const CORE_GROUPS = new Set(['C', 'D', 'E', 'F', 'G', 'H']);

const WAVE_TITLES = {
  1: 'Wave 1: finish items that were waiting on production migrations',
  2: 'Wave 2: switch on and wire up what is already built (flag off or not mounted)',
  3: 'Wave 3: finish half-built features',
  4: 'Wave 4: build missing core product features (chat, files, research, media, tools, agents)',
  5: 'Wave 5: build the remaining missing features (platforms, models, billing, admin, backend, ecosystem)',
};

function readLedger() {
  const text = fs.readFileSync(path.join(root, LEDGER), 'utf8');
  return text
    .split('\n')
    .filter(Boolean)
    .map((line, index) => {
      try {
        return JSON.parse(line);
      } catch (error) {
        throw new Error(`${LEDGER}:${index + 1} is not valid JSON: ${error.message}`);
      }
    });
}

function expectedRollup(item) {
  if (item.rollup === 'declined' || !item.cells || !Object.keys(item.cells).length)
    return item.rollup;
  const applicable = Object.values(item.cells)
    .map((entry) => entry.s)
    .filter((status) => status !== 'n/a');
  if (!applicable.length) return 'n/a';
  for (const status of ['done', 'missing', 'unverified'])
    if (applicable.every((value) => value === status)) return status;
  return 'partial';
}

function normalizeRollups() {
  const file = path.join(root, LEDGER);
  const drift = [];
  const lines = fs
    .readFileSync(file, 'utf8')
    .split('\n')
    .map((line) => {
      if (!line) return line;
      const item = JSON.parse(line);
      const expected = expectedRollup(item);
      if (expected === item.rollup) return line;
      drift.push(`${item.id} says ${item.rollup}, its cells say ${expected}`);
      return line.replace(`"rollup": "${item.rollup}"`, `"rollup": "${expected}"`);
    });
  return { drift, text: lines.join('\n') };
}

function slug(title) {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 60)
    .replace(/-$/, '');
}

function cell(text) {
  return String(text ?? '')
    .replace(/\s+/g, ' ')
    .replace(/[\\|]/g, '\\$&')
    .trim();
}

function surfacesOf(item) {
  return SURFACES.filter((surface) => item.cells[surface]);
}

function cellsWith(item, status) {
  return surfacesOf(item).filter((surface) => item.cells[surface].s === status);
}

function isOpen(item) {
  return item.rollup === 'partial' || item.rollup === 'missing';
}

function waveOf(item) {
  if (item.rollup === 'missing') return CORE_GROUPS.has(item.group) ? 4 : 5;
  const links = new Set(
    cellsWith(item, 'partial').flatMap((surface) => item.cells[surface].miss ?? []),
  );
  if (links.has('pending-migration')) return 1;
  if (links.has('flag-off') || links.has('mount')) return 2;
  return 3;
}

function evidence(item, surfaces) {
  const seen = new Set();
  const out = [];
  for (const surface of surfaces) {
    for (const ev of item.cells[surface].ev ?? []) {
      const where = ev.l ? `${ev.p}:${ev.l.join('-')}` : ev.p;
      if (seen.has(where)) continue;
      seen.add(where);
      out.push(`\`${where}\``);
      if (out.length === 4) return out;
    }
  }
  return out;
}

function header(kind, section, title, meta) {
  const what = {
    missing: 'features that do not exist yet',
    partial: 'features that exist but are not finished',
    'live-check': 'cells that only a check against the running product can settle',
  }[kind];
  return [
    `# ${section}. ${title}: ${kind === 'live-check' ? 'needs a live check' : kind}`,
    '',
    `Open ${what}, from the code audit of \`${meta.auditedCommit.slice(0, 9)}\`.`,
    'Generated by `scripts/audit-worklist.mjs`; do not edit by hand. When an item is',
    `resolved, mark its cells \`done\` with evidence in \`${LEDGER}\` and run`,
    '`pnpm audit:worklist`. The item then leaves this file, and the file is deleted when',
    'nothing is left.',
    '',
  ];
}

function renderPartial(items) {
  const lines = [];
  for (const item of items) {
    const works = cellsWith(item, 'done');
    const open = surfacesOf(item).filter((surface) =>
      ['partial', 'missing'].includes(item.cells[surface].s),
    );
    lines.push(`## ${item.id}: ${item.text}`, '');
    lines.push(`- Done when: ${item.criterion ?? item.text}`);
    lines.push(`- Wave: ${waveOf(item)}`);
    if (works.length) lines.push(`- Already works on: ${works.join(', ')}`);
    if (item.productDecisionNeeded)
      lines.push(`- Needs a founder decision: ${cell(item.productDecisionNeeded)}`);
    lines.push('', '| Surface | Status | What is left | Gap |', '| --- | --- | --- | --- |');
    for (const surface of open) {
      const c = item.cells[surface];
      const left = c.s === 'missing' ? 'Not built on this surface.' : c.remaining;
      lines.push(`| ${surface} | ${c.s} | ${cell(left)} | ${cell((c.miss ?? []).join(', '))} |`);
    }
    const ev = evidence(item, cellsWith(item, 'partial'));
    if (ev.length) lines.push('', `Code: ${ev.join(', ')}`);
    lines.push('');
  }
  return lines;
}

function renderMissing(items) {
  const lines = [];
  for (const item of items) {
    const needed = cellsWith(item, 'missing');
    lines.push(`## ${item.id}: ${item.text}`, '');
    lines.push(`- Done when: ${item.criterion ?? item.text}`);
    lines.push(`- Wave: ${waveOf(item)}`);
    lines.push(`- Build on: ${needed.join(', ') || 'see criterion'}`);
    if (item.productDecisionNeeded)
      lines.push(`- Needs a founder decision: ${cell(item.productDecisionNeeded)}`);
    const notes = needed.map((surface) => item.cells[surface].why).filter(Boolean);
    if (notes.length) lines.push(`- Note: ${cell(notes[0])}`);
    lines.push('');
  }
  return lines;
}

function renderLiveCheck(items) {
  const lines = ['| Item | Surface | What would settle it |', '| --- | --- | --- |'];
  for (const item of items) {
    for (const surface of cellsWith(item, 'unverified')) {
      const c = item.cells[surface];
      lines.push(`| ${item.id}: ${cell(item.text)} | ${surface} | ${cell(c.settleBy ?? c.why)} |`);
    }
  }
  lines.push('');
  return lines;
}

function build() {
  const items = readLedger();
  const meta = JSON.parse(fs.readFileSync(path.join(root, META), 'utf8'));
  const bySection = new Map();
  for (const item of items) {
    if (!bySection.has(item.section)) bySection.set(item.section, []);
    bySection.get(item.section).push(item);
  }

  const files = new Map();
  const waveSections = new Map();
  for (const [section, sectionItems] of [...bySection].sort((a, b) => a[0] - b[0])) {
    const title = meta.sections[String(section)] ?? `Section ${section}`;
    const name = `${String(section).padStart(3, '0')}-${slug(title)}.md`;
    const kinds = {
      missing: sectionItems.filter((item) => item.rollup === 'missing'),
      partial: sectionItems.filter((item) => item.rollup === 'partial'),
      'live-check': sectionItems.filter((item) => cellsWith(item, 'unverified').length > 0),
    };
    const render = {
      missing: renderMissing,
      partial: renderPartial,
      'live-check': renderLiveCheck,
    };
    for (const [kind, list] of Object.entries(kinds)) {
      if (!list.length) continue;
      const body = [...header(kind, section, title, meta), ...render[kind](list)];
      files.set(`audit/${kind}/${name}`, `${body.join('\n').trimEnd()}\n`);
    }
    for (const item of sectionItems.filter(isOpen)) {
      const wave = waveOf(item);
      const key = `${wave}:${section}`;
      if (!waveSections.has(key))
        waveSections.set(key, { wave, section, title, name, missing: 0, partial: 0 });
      waveSections.get(key)[item.rollup] += 1;
    }
  }

  files.set(WAVES, renderWaves(items, waveSections, files));
  return files;
}

function renderWaves(items, waveSections, files) {
  const count = (rollup) => items.filter((item) => item.rollup === rollup).length;
  const unverifiedCells = items.reduce((n, item) => n + cellsWith(item, 'unverified').length, 0);
  const blockers = fs.existsSync(path.join(root, 'audit/blockers'))
    ? fs
        .readdirSync(path.join(root, 'audit/blockers'))
        .filter((f) => f.endsWith('.md'))
        .sort()
    : [];
  const lines = [
    '# Resolution waves',
    '',
    'Generated by `scripts/audit-worklist.mjs`; do not edit by hand. Counts shrink as',
    `items are marked \`done\` in \`${LEDGER}\`.`,
    '',
    `Open now: ${count('missing')} missing items, ${count('partial')} partial items and`,
    `${unverifiedCells} cells that need a live check, out of ${items.length} audited items`,
    `(${count('done')} done, ${count('declined')} declined by decision, ${count('n/a')} not applicable).`,
    '',
    'Waves run in order. Within a wave, work section by section: each link opens the file',
    'that lists every open item with what is left per surface.',
    '',
    '## Wave 0: release blockers and security',
    '',
    'Fix these first. Each file is one defect; delete it when the fix lands and its',
    'ledger cells are updated.',
    '',
    ...(blockers.length ? blockers.map((f) => `- [${f}](../blockers/${f})`) : ['- None open.']),
    '',
  ];
  for (const wave of [1, 2, 3, 4, 5]) {
    const rows = [...waveSections.values()]
      .filter((row) => row.wave === wave)
      .sort((a, b) => a.section - b.section);
    const total = rows.reduce((n, row) => n + row.missing + row.partial, 0);
    lines.push(`## ${WAVE_TITLES[wave]}`, '', `${total} open items.`, '');
    if (!rows.length) {
      lines.push('Nothing left in this wave.', '');
      continue;
    }
    lines.push('| Section | Items | File |', '| --- | ---: | --- |');
    for (const row of rows) {
      const kind = row.missing ? 'missing' : 'partial';
      const file = `audit/${kind}/${row.name}`;
      const link = files.has(file) ? `[${kind}/${row.name}](../${kind}/${row.name})` : '';
      lines.push(`| ${row.section}. ${cell(row.title)} | ${row.missing + row.partial} | ${link} |`);
    }
    lines.push('');
  }
  lines.push(
    '## Wave 6: live checks and cleanup',
    '',
    `- ${unverifiedCells} cells in \`audit/live-check/\` need the running product to settle.`,
    '- `audit/live-check/codex-live-verification-queue.md` is the queue for the live-check agent.',
    '- `audit/doc-corrections/` lists documents that disagree with the code.',
    '- `audit/prior-audits/` holds earlier audits; delete each one once everything it',
    '  reports is fixed.',
    '',
  );
  return `${lines.join('\n').trimEnd()}\n`;
}

function listGenerated() {
  const out = [];
  for (const dir of GENERATED_DIRS) {
    const abs = path.join(root, dir);
    if (!fs.existsSync(abs)) continue;
    for (const name of fs.readdirSync(abs))
      if (GENERATED_FILE.test(name)) out.push(`${dir}/${name}`);
  }
  return out;
}

const check = process.argv.includes('--check');
const problems = [];
const rollups = normalizeRollups();
if (rollups.drift.length) {
  if (check)
    problems.push(
      `${rollups.drift.length} ledger items have a rollup that disagrees with their cells (${rollups.drift.slice(0, 3).join('; ')})`,
    );
  else fs.writeFileSync(path.join(root, LEDGER), rollups.text);
}
const files = build();

for (const [file, content] of files) {
  const abs = path.join(root, file);
  const current = fs.existsSync(abs) ? fs.readFileSync(abs, 'utf8') : null;
  if (current === content) continue;
  if (check) {
    problems.push(`${file} is ${current === null ? 'missing' : 'stale'}`);
  } else {
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    fs.writeFileSync(abs, content);
  }
}
for (const file of listGenerated()) {
  if (files.has(file)) continue;
  if (check) problems.push(`${file} has no open items left; delete it`);
  else fs.rmSync(path.join(root, file));
}

if (problems.length) {
  console.error(
    `audit worklist is out of date:\n- ${problems.join('\n- ')}\nRun pnpm audit:worklist.`,
  );
  process.exit(1);
}
console.log(
  check
    ? `audit worklist is current (${files.size} files).`
    : `audit worklist written (${files.size} files).`,
);
